// Did the twice-daily health check run? A pure function of the clock and the health_runs rows.
// The answer is about the most recent 06:00 or 18:00 run whose deadline (start + grace) has passed.
function lastRun({ now, runs, timezone, hours, graceMinutes }) {
  const at = DateTime.fromISO(now).setZone(timezone);
  let slot = null;
  for (let d = 0; d < 3 && !slot; d++) {
    for (const h of [...hours].sort((a, b) => b - a)) {
      const s = at.minus({ days: d }).set({ hour: h, minute: 0, second: 0, millisecond: 0 });
      if (s.plus({ minutes: graceMinutes }) <= at) { slot = s; break; }
    }
  }
  const expectedBy = slot.plus({ minutes: graceMinutes });
  const label = slot.toFormat('HH:mm');
  const mine = runs
    .filter((r) => r && r.scheduled_for && DateTime.fromISO(r.scheduled_for).toMillis() === slot.toMillis())
    .sort((a, b) => String(b.started_at).localeCompare(String(a.started_at)));
  const finished = mine.find((r) => r.finished_at && DateTime.fromISO(r.finished_at) <= expectedBy);
  const run = finished || mine[0] || null;
  let ok = false;
  let message;
  if (finished) {
    ok = true;
    message = `Health check for ${label} finished at ${DateTime.fromISO(finished.finished_at).setZone(timezone).toFormat('HH:mm')}.`;
  } else if (!run) {
    message = `Health check did not run at ${label} ${timezone}: no run was recorded.`;
  } else if (!run.finished_at) {
    message = `Health check started at ${label} ${timezone} but did not finish: the n8n execution failed or is stuck.`;
  } else {
    message = `Health check for ${label} ${timezone} finished late, at ${DateTime.fromISO(run.finished_at).setZone(timezone).toFormat('HH:mm')}.`;
  }
  return {
    ok,
    last_run: run ? { run_id: run.run_id, started_at: run.started_at, finished_at: run.finished_at || null, status: run.status } : null,
    expected_by: expectedBy.toUTC().toISO(),
    message,
  };
}

// Answers only callers inside the cluster. The n8n Ingress routes every /webhook/* path, and Traefik
// forwards the public Host and adds X-Forwarded-For; a caller using the Service name sends neither.
const IN_CLUSTER_HOST = 'n8n.n8n.svc.cluster.local';
const headers = $('Last Run Request').first().json.headers || {};
const host = String(headers.host || '').split(':')[0].toLowerCase();
if (host !== IN_CLUSTER_HOST || headers['x-forwarded-for'] || headers['x-forwarded-host'] || headers['x-real-ip']) {
  return [{ json: { code: 404, body: { code: 404, message: 'Not found' } } }];
}
const read = $('Get Runs').all().map((i) => i.json);
const failed = read.find((r) => r.error);
if (failed) {
  return [{ json: { code: 200, body: { ok: false, last_run: null, expected_by: null,
    message: `Health check state could not be read: ${String(failed.error.message || failed.error).slice(0, 160)}` } } }];
}
const body = lastRun({ now: DateTime.now().toUTC().toISO(), runs: read.filter((r) => r.run_id),
  timezone: 'America/New_York', hours: [6, 18], graceMinutes: 20 });
return [{ json: { code: 200, body } }];
